// Build-time access to the catalog (src/data/catalog.json, generated by `npm run catalog`). Never import this from a
// client <script>: it would bundle the whole JSON. The browser fetches /catalogo/productos.json instead.
import catalog from '../data/catalog.json';
import type { CatalogPayload } from './catalog-search';

export interface Producto {
  cod: string;
  /** Supplier codes that lead to this product (its own first, then retired duplicates'), space-separated. Search and
   * saved quote lists still find it by them. */
  antes?: string;
  nombre: string;
  categoria: string;
  segmento: string;
  bajoPedido: boolean;
}

export const updatedAt = catalog.updatedAt;
export const total = catalog.total;
export const categorias = catalog.categorias;
export const segmentos = catalog.segmentos;

// Some names start with a model number ("122 CAMILLA…"); those go after the ones that start with a word.
const startsWithDigit = (p: Producto) => /^\d/.test(p.nombre);
const byName = (a: Producto, b: Producto) =>
  Number(startsWithDigit(a)) - Number(startsWithDigit(b)) || a.nombre.localeCompare(b.nombre, 'es');
/** Alphabetical by name: the order people scan a list in. */
export const productos: Producto[] = [...catalog.productos].sort(byName);

export const categoriaPath = (slug: string) => `/catalogo/${slug}/`;

/** "2026-11-09" → "9 de noviembre de 2026" */
export const formatDate = (iso: string) =>
  new Date(`${iso}T12:00:00`).toLocaleDateString('es-CO', { day: 'numeric', month: 'long', year: 'numeric' });

export function payload(): CatalogPayload {
  const cat = new Map(categorias.map((c, i) => [c.slug, i]));
  const seg = new Map(segmentos.map((s, i) => [s.slug, i]));
  return {
    updatedAt,
    categorias: categorias.map(({ slug, label, comun }) => ({ slug, label, comun })),
    segmentos: segmentos.map(({ slug, label }) => ({ slug, label })),
    productos: productos.map((p) => [p.cod, p.nombre, cat.get(p.categoria)!, seg.get(p.segmento)!, p.bajoPedido ? 1 : 0, p.antes ?? '']),
  };
}
